def first_Digit(n):
    """Return the first (most significant) digit of an integer n."""
    # Handle negative numbers by taking absolute value
    if isinstance(n, int):
        n = abs(n)

    # Convert to string and return the first character as a digit
    s_n = str(n)
    return int(s_n[0])


# Example usage / assertion from your prompt:
assert first_Digit(123) == 1
